/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNumberArray = require( '@stdlib/assert/is-number-array' );
var isStringArray = require( '@stdlib/assert/is-number-array' );
var isEmptyArray = require( '@stdlib/assert/is-empty-array' );
var isCollection = require( '@stdlib/assert/is-collection' );
var format = require( '@stdlib/string/format' );
var everyBy2 = require( '@stdlib/plot/unicode/base/lib/every_by2.js' );


// FUNCTIONS //

/**
* Predicate function which tests whether two elements are equal.
*
* @private
* @param {Object} v1 - first value
* @param {Object} v2 - second value
* @returns {boolean} boolean indicating whether two elements are equal
*/
function predicate( v1, v2 ) {
	return ( v1 === v2 );
}


// MAIN //

/**
* Sets the x axis tics labels.
*
* @private
* @param {Array} value - Array of tics labels
* @throws {TypeError} must be a array of string or number literals
*/
function set( value ) {
	var isChange;
	var data;
	var i;

	data = this._axisDataObjs[ 0 ].rawLabels;
	data.length = value.length;
	if ( !isNumberArray( value ) && !isStringArray( value ) && !isEmptyArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` array of string or number literals is expected. Value: `%s`.', 'xAxisTicsLabel', value ) );
	}
	if ( !this._axisDataObjs[ 0 ].axis && data.length === value.length && everyBy2( data, value, predicate ) ) {
		isChange = false;
	}
	else {
		isChange = true;
	}
	if ( isChange ) {
		this._axisDataObjs[ 0 ].axis = true;
		for ( i = 0; i < value.length; i++ ) {
			data[ i ] = value[ i ];
		}
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
